"""Freeze checked scale art without replacing previous review packages."""
from pathlib import Path
import json,hashlib,shutil,sys,zipfile

small,large,comparison,target=map(Path,sys.argv[1:]);repo=Path(__file__).resolve().parents[3]
assert not target.exists(),'Never overwrite an earlier review'
provenance=json.loads((repo/'art/generated-galaxy-m1/scale-v4/source-provenance.json').read_text(encoding='utf-8'))
for item in provenance['files']:assert hashlib.sha256((repo/'art/generated-galaxy-m1/scale-v4'/item['file']).read_bytes()).hexdigest()==item['sha256']
checks=[]
for source,sub,count in [(small,'verification-recovered1',250),(large,'verification-recovered2',1000)]:
    c=json.loads((source/'review-checks.json').read_text(encoding='utf-8'));v=json.loads((source/sub/'browser-parity.json').read_text(encoding='utf-8'));p=json.loads((source/sub/'portal-proof.json').read_text(encoding='utf-8'))
    assert not c['errors']and v['passed']and p['passed']and c['systemCount']==count
    for row in c['captures']:assert hashlib.sha256((source/row['file']).read_bytes()).hexdigest()==row['sha256']
    for row in c['sourceHashes']:assert hashlib.sha256((repo/'tools/art/scaled-galaxy-m1'/row['file']).read_bytes()).hexdigest()==row['sha256']
    checks.append((c,v,p))
assert checks[0][0]['sourceHashes']==checks[1][0]['sourceHashes']
target.mkdir(parents=True);shutil.copytree(small,target/'250');shutil.copytree(large,target/'1000');shutil.copytree(comparison,target/'comparison')
shutil.copytree(repo/'art/generated-galaxy-m1/scale-v4',target/'source-samples');shutil.copytree(repo/'tools/art/scaled-galaxy-m1',target/'renderer-source')
for f in ['handoff.md','presentation-contract.md']:shutil.copy2(repo/'docs/art/generated-galaxy-m1/scale-v4'/f,target/f)
idx=json.loads((target/'source-samples/sample-index.json').read_text(encoding='utf-8'));rows=[]
for i in idx['samples']:
    r=json.loads((target/'source-samples'/i['report']).read_text(encoding='utf-8-sig'));d=r['Diagnostics'];largest=max(len(c['NodeIds'])for c in d['QuietComponents'])
    rows.append(f'<tr><td>{i["seed"]} /{i["systemCount"]}</td><td>{d["QuietEmptySystemMeanAreaRatio"]:.4f}</td><td>{len(d["QuietEmptyNodeIds"])} /{len(d["DisturbedEmptyNodeIds"])}</td><td>{d["QuietComponentCount"]} /{largest}</td><td>{d["SystemPairCrossingsMaximum"]}</td></tr>')
html='''<!doctype html><html lang="en"><meta charset="utf-8"><title>M1 scaled geography art review</title><style>body{background:#050a10;color:#eeeaf2;font:18px Segoe UI;margin:28px}a{color:#9fd8fb}p{max-width:1250px;line-height:1.5}img{width:100%;border:1px solid #45566a}.grid{display:grid;grid-template-columns:1fr 1fr;gap:24px}h1,h2{color:#efb16b;font-weight:500}td,th{padding:12px;text-align:left;border-bottom:1px solid #45566a}.notice{padding:18px;background:#101b29;border-left:5px solid #efb16b;max-width:1250px}</style><h1>M1 / larger galaxies and truthful route drawing</h1><div class="notice">Review250 first, then1000 stress views. Actual portable candidate data; these browser artifacts do not establish Unity/native acceptance. Earlier delivered galleries and game packages remain preserved.</div><p>One connected5:4extent. Crooked junctions stay intact. Accepted routes pass through actual shared edges, without changing nodes, crossings or costs. Quiet-space sets use real report memberships, with no invented galaxy-spanning corridor.</p><div class="grid"><section><h2>250-system review</h2><a href="250/review.html"><img src="250/standard-overview.png" alt="Actual250-system map"></a><p><a href="250/review.html">36captures / three sizes</a> · <a href="250/index.html">Interactive candidate</a> · <a href="250/verification-recovered1/browser-parity.json">Browser checks</a> · <a href="250/verification-recovered1/portal-proof.json">Integer portal proof</a></p></section><section><h2>1000-system stress presentation</h2><a href="1000/review.html"><img src="1000/standard-overview.png" alt="Actual1000-system map"></a><p><a href="1000/review.html">18captures / three sizes</a> · <a href="1000/index.html">Interactive candidate</a> · <a href="1000/verification-recovered2/browser-parity.json">Browser checks</a> · <a href="1000/verification-recovered2/portal-proof.json">Integer portal proof</a></p></section></div><h2>Measured quiet space / actual seeded samples</h2><table><tr><th>Seed / systems</th><th>Quiet/system mean area</th><th>Quiet / disturbed empty</th><th>Quiet sets / largest</th><th>Maximum system crossings</th></tr>'''+''.join(rows)+'''</table><p>These ratios are soft generation outcomes. Quiet is sampled site pressure, not whole-cell coverage, ownership or sensor knowledge. Fragmented connected sets do not guarantee a galaxy-spanning quiet corridor.</p><h2>Why shared-edge portals matter</h2><a href="comparison/portal-comparison.png"><img src="comparison/portal-comparison.png" alt="Same real cells, reproduced old chord rule and exact portal rule"></a><p>Both panels use the same real250export and one accepted hop. Left reproduces the previous drawing rule; it is not a screenshot of an older executable. A portal is a drawing vertex, never another navigation step. <a href="comparison/portal-comparison.json">Exact source/intersection facts</a>.</p><p><a href="handoff.md">Detailed handoff, limitations and interrupted-test receipts</a> · <a href="source-samples/diagnostic-parity.json">Independent report parity</a> · <a href="source-samples/sample-index.json">Raw source pins</a> · <a href="source-samples/source-provenance.json">Per-file Git provenance</a> · <a href="source-samples/tokens.json">Presentation tokens</a></p><p>216overview pointer checks plus separate zoom disambiguation;3750all-centre model checks. Subpixel stars can share a received overview pixel: nearest picking follows the actual pointer, and local zoom separates the tested ambiguities. No geometry or alignment tolerance was relaxed. No new gameplay, sensors, hazards, AI, M2 or default activation.</p></html>'''
(target/'review.html').write_text(html,encoding='utf-8')
receipt={'status':'M1 scale art/browser evidence; native and owner acceptance separate','backendCommit':idx['backendCommit'],'entry':str(target/'review.html'),'captures250':len(checks[0][0]['captures']),'captures1000':len(checks[1][0]['captures']),'overviewPointerChecks':sum(o['actualDenseStarClicks']for _,v,_ in checks for o in v['observations']),'nearestCentreModelChecks':sum(o['parity']['systems']for _,v,_ in checks for o in v['observations']),'portalsProvedAcrossViews':sum(r['portalsProved']for _,_,p in checks for r in p['results']),'intraCellSegmentsProvedAcrossViews':sum(r['convexIntraCellSegmentsProved']for _,_,p in checks for r in p['results']),'priorGalleriesPreserved':True}
payload=[{'file':p.relative_to(target).as_posix(),'bytes':p.stat().st_size,'sha256':hashlib.sha256(p.read_bytes()).hexdigest()}for p in sorted(target.rglob('*'))if p.is_file()]
(target/'payload-manifest.json').write_text(json.dumps(payload,indent=2)+'\n',encoding='utf-8')
archive=target/'HobbyDS9-M1-Scale-Art-v4.zip'
with zipfile.ZipFile(archive,'w',zipfile.ZIP_DEFLATED)as z:
    for p in sorted(target.rglob('*')):
        if p.is_file()and p!=archive:z.write(p,p.relative_to(target))
receipt.update(zipBytes=archive.stat().st_size,zipSha256=hashlib.sha256(archive.read_bytes()).hexdigest());(target/'delivery.json').write_text(json.dumps(receipt,indent=2)+'\n',encoding='utf-8');print(json.dumps(receipt))
